<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {scheduleApi} from '../schedules'
const props=defineProps<{manage?:boolean}>()
const emit=defineEmits<{busy:[value:boolean]}>()
type Hour={day:number;state:'unknown'|'open'|'closed';opens:string;closes:string}
type Info={name:string;location:string;hours:Hour[];notice_date:string|null;notice:string;closed_for_notice:boolean;published:boolean;version:number;updated_at?:string}
const empty=():Info=>({name:'',location:'',hours:Array.from({length:7},(_,i)=>({day:i+1,state:'unknown',opens:'',closes:''})),notice_date:null,notice:'',closed_for_notice:false,published:false,version:0})
const form=ref<Info>(empty()),exists=ref(false),loading=ref(false),saving=ref(false),ready=ref(false),error=ref(''),message=ref(''),today=ref(''),baseline=ref('')
const weekdays=[{id:7,name:'Sunday'},{id:1,name:'Monday'},{id:2,name:'Tuesday'},{id:3,name:'Wednesday'},{id:4,name:'Thursday'},{id:5,name:'Friday'},{id:6,name:'Saturday'}]
const dirty=computed(()=>ready.value && JSON.stringify(form.value)!==baseline.value)
const hours=computed(()=>weekdays.map(d=>({...d,hour:form.value.hours.find(h=>h.day===d.id)!})))
const dayId=computed(()=>today.value?(new Date(today.value+'T00:00:00Z').getUTCDay()||7):0)
const todayHour=computed(()=>form.value.hours.find(h=>h.day===dayId.value))
let timer:ReturnType<typeof setTimeout>|undefined
watch(message,value=>{clearTimeout(timer);if(value)timer=setTimeout(()=>message.value='',4000)})
onBeforeUnmount(()=>clearTimeout(timer))
async function load(force=false){if(dirty.value&&!force&&!window.confirm('Discard unsaved canteen details and reload?'))return;loading.value=true;error.value='';ready.value=false
 try{const result=await scheduleApi(props.manage?'canteen/info':'student/canteen/info');form.value=result.info??empty();exists.value=Boolean(result.info);today.value=result.today;baseline.value=JSON.stringify(form.value);ready.value=true}catch(e){error.value=e instanceof Error?e.message:'Unable to load canteen details.';exists.value=false}finally{loading.value=false}}
async function save(){if(!ready.value||saving.value)return;saving.value=true;emit('busy',true);error.value='';message.value='';try{const result=await scheduleApi('canteen/info','PUT',form.value);await load(true);if(!error.value)message.value=result.message}catch(e){error.value=e instanceof Error?e.message:'Unable to save. Your changes remain in the form.'}finally{saving.value=false;emit('busy',false)}}
function useSchoolHours(){form.value.hours=weekdays.map(d=>({day:d.id,state:d.id===6?'closed':'open',opens:d.id===6?'':'10:00',closes:d.id===6?'':'16:00'}))}
onMounted(()=>load())
</script>
<template>
<section class="canteen-details"><div class="section-heading"><div><p class="eyebrow">{{manage?'SCHOOL CANTEEN SETTINGS':'SCHOOL CANTEEN'}}</p><h2>{{manage?'Hours & location':(form.name||'Canteen information')}}</h2></div><button type="button" class="secondary" :disabled="loading||saving" @click="load()">Refresh</button></div>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><p v-if="loading" role="status">Loading canteen details…</p>
<form v-if="manage&&ready" @submit.prevent="save"><fieldset :disabled="saving||loading"><div class="details-card"><h3>Canteen identity</h3><div class="two-fields"><label>Canteen name<input v-model="form.name" maxlength="100" :required="form.published" placeholder="School canteen"></label><label>Location in school<input v-model="form.location" maxlength="250" :required="form.published" placeholder="Building, floor or nearby landmark"></label></div><p class="hint">Publish school-approved details only. Draft information is hidden from students.</p></div>
<div class="details-card"><div class="section-heading"><h3>Weekly opening hours</h3><button type="button" class="secondary small" @click="useSchoolHours">Use Sun–Fri, 10 AM–4 PM</button></div><p class="hint">Nepal time. Choose Unknown when hours have not been confirmed. The shortcut only fills this draft.</p><div class="hours-scroll"><table><thead><tr><th>Day</th><th>Service</th><th>Opens</th><th>Closes</th></tr></thead><tbody><tr v-for="row in hours" :key="row.id"><th scope="row">{{row.name}}</th><td><select v-model="row.hour.state" :aria-label="row.name+' service state'"><option value="unknown">Unknown</option><option value="open">Open at set hours</option><option value="closed">Closed</option></select></td><td><input v-model="row.hour.opens" type="time" :disabled="row.hour.state!=='open'" :required="row.hour.state==='open'" :aria-label="row.name+' opening time'"></td><td><input v-model="row.hour.closes" type="time" :min="row.hour.opens" :disabled="row.hour.state!=='open'" :required="row.hour.state==='open'" :aria-label="row.name+' closing time'"></td></tr></tbody></table></div></div>
<div class="details-card"><h3>Notice for one date</h3><div class="two-fields"><label>Applicable date<input v-model="form.notice_date" type="date" :required="Boolean(form.notice.trim())"></label><label>Notice<input v-model="form.notice" maxlength="500" :required="Boolean(form.notice_date)" placeholder="For example: closed for school maintenance"></label></div><label class="check"><input v-model="form.closed_for_notice" type="checkbox">Canteen is closed on this date</label><button type="button" class="text-button" @click="form.notice='';form.notice_date=null;form.closed_for_notice=false">Clear notice</button><p class="hint">The notice is shown to students only on its applicable Nepal date.</p></div>
<div class="save-bar"><label class="check"><input v-model="form.published" type="checkbox">Publish canteen details</label><span class="hint">{{dirty?'Unsaved changes':form.published?'Published details':'Draft only'}}</span><button :disabled="!dirty||saving">{{saving?'Saving…':'Save details'}}</button></div></fieldset></form>
<template v-else-if="!manage&&ready"><p v-if="!exists" class="hint">The canteen head has not published hours and location yet.</p><div v-else class="student-info"><p class="location">{{form.location}}</p><p v-if="form.closed_for_notice&&form.notice_date===today" class="closure">Closed today · {{form.notice}}</p><template v-else><p v-if="form.notice" class="notice">{{form.notice}}</p><p v-if="todayHour?.state==='open'"><strong>Today’s hours:</strong> {{todayHour.opens}}–{{todayHour.closes}} (Nepal time)</p><p v-else-if="todayHour?.state==='closed'">Closed today.</p><p v-else>Today’s opening hours have not been confirmed.</p></template><details><summary>Weekly hours</summary><ul><li v-for="row in hours" :key="row.id"><strong>{{row.name}}</strong><span>{{row.hour.state==='open'?row.hour.opens+'–'+row.hour.closes:row.hour.state==='closed'?'Closed':'Not confirmed'}}</span></li></ul></details></div></template>
<p v-if="form.updated_at&&ready" class="hint">Details updated {{new Date(form.updated_at).toLocaleString(undefined,{timeZone:'Asia/Kathmandu'})}} · Nepal time</p>
</section>
</template>
<style scoped>
.canteen-details{min-width:0}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:16px}.section-heading h2,.section-heading h3{margin:0}.section-heading h3{flex:1}.section-heading>button{width:auto;flex-shrink:0;white-space:nowrap}.save-bar>button{width:auto}.details-card,.student-info{background:white;border:1px solid #d9e4dc;border-radius:14px;padding:20px;margin:16px 0}.details-card h3{margin:0 0 12px;font-size:17px}.two-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}fieldset{border:0;padding:0;min-width:0}label{display:block;font-size:13px;font-weight:600}input,select{width:100%;box-sizing:border-box;min-width:0;font:inherit;padding:10px;border:1px solid #c4d4c9;border-radius:7px;margin-top:6px;background:#fff;color:#263e33}.hint{font-size:12px;color:#687d70;line-height:1.6}.hours-scroll{overflow:auto}table{width:100%;border-collapse:collapse;min-width:480px;font-size:13px;text-align:left}th,td{padding:8px;border-bottom:1px solid #e1e9e3}thead{background:#f2f6f3}table input,table select{margin:0;font-size:12px;padding:8px}.check{display:flex;align-items:center;gap:9px;margin:12px 0}.check input{width:17px;height:17px;margin:0}.save-bar{display:flex;align-items:center;gap:16px;flex-wrap:wrap;background:#e7f0e9;border-radius:12px;padding:12px 16px}.save-bar button{margin-left:auto}.small{font-size:12px;padding:8px 12px}.text-button{background:transparent;color:#456d55;font-size:12px;text-decoration:underline;padding:5px 0}.location{font-weight:600}.closure,.notice{padding:12px;background:#fff2d8;color:#765820;border-radius:8px}.student-info ul{list-style:none;padding:0;margin:12px 0}.student-info li{display:flex;justify-content:space-between;font-size:13px;gap:16px;padding:8px 0;border-bottom:1px solid #e5ece7}summary{cursor:pointer;font-weight:600;font-size:13px}@media(max-width:650px){.two-fields{grid-template-columns:1fr}.section-heading{align-items:flex-start;flex-wrap:wrap}.details-card{padding:14px}.save-bar button{width:100%;margin:0}}
</style>
